/**
 * 中国省-市-县（区）三级行政区划与政府驻地经纬度，用于出生地逐级选择与真太阳时经度校正。
 * 数据来源：国家统计局历年行政区划（经 AreaCity-JsSpider-StatsGov 整理，2025 版），
 * 经纬度为各行政区政府驻地坐标，保留两位小数（经度 0.01° 约合时间 2.4 秒，可忽略）。
 * 紧凑编码：每行一个省级单位「省名\\t时区键\\t城市…」，城市间 / 分隔，
 * 城市为「市名,经度,纬度[|县名,经度,纬度;…]」；海外组县级位存放「时区,偏移分钟」。
 */
export interface AreaNode {
  /** 县（区）名 */
  n: string;
  /** 政府驻地经度 */
  lon: number;
  /** 政府驻地纬度 */
  lat: number;
}

export interface CityNode {
  n: string;
  lon: number;
  lat: number;
  areas: AreaNode[];
  /** 海外城市的 IANA 时区（覆盖省级默认） */
  zone?: string;
  /** 海外城市的标准时区偏移分钟（覆盖省级默认） */
  off?: number;
}

export interface ProvinceNode {
  n: string;
  zone: string;
  off: number;
  cities: CityNode[];
}

